//! Differential ratchet for
//! `src/engine/battleScriptTrysetgrudgeOpcode.ts`. Expected complete projected
//! results, controls, and the exact missing-role error are generated by
//! invoking the canonical TypeScript opcode handler; regenerate with
//! `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-trysetgrudge-vectors.mjs`.

use std::collections::BTreeSet;

use factory_core::battle_script_trysetgrudge::{
    apply_battle_script_trysetgrudge, BattleScriptTrysetgrudgeBattlerState,
    BattleScriptTrysetgrudgeControl, BattleScriptTrysetgrudgeOutcome,
    BattleScriptTrysetgrudgeRoles, BattleScriptTrysetgrudgeRules, BATTLE_SCRIPT_STATUS3_GRUDGE,
    BATTLE_SCRIPT_TRYSETGRUDGE_BATTLERS, BATTLE_SCRIPT_TRYSETGRUDGE_BATTLER_COUNT,
};
use factory_core::battle_script_trysetgrudge_vectors_gen::{
    BattleScriptTrysetgrudgeVectorCase, BattleScriptTrysetgrudgeVectorState,
    BATTLE_SCRIPT_TRYSETGRUDGE_ATTACKER_DOMAIN, BATTLE_SCRIPT_TRYSETGRUDGE_BRANCH_CENSUS,
    BATTLE_SCRIPT_TRYSETGRUDGE_CASES, BATTLE_SCRIPT_TRYSETGRUDGE_CATEGORY_CENSUS,
    BATTLE_SCRIPT_TRYSETGRUDGE_DOMAIN_CENSUS, BATTLE_SCRIPT_TRYSETGRUDGE_GRUDGE_INPUT_DOMAIN,
    BATTLE_SCRIPT_TRYSETGRUDGE_STATUS3_EDGE_DOMAIN,
    BATTLE_SCRIPT_TRYSETGRUDGE_VECTOR_CORPUS_SHA256,
};

fn rules(value: BattleScriptTrysetgrudgeVectorState) -> BattleScriptTrysetgrudgeRules {
    BattleScriptTrysetgrudgeRules {
        battlers: value
            .status3
            .map(|status3| BattleScriptTrysetgrudgeBattlerState { status3 }),
        selector_roles: BattleScriptTrysetgrudgeRoles { attacker: value.attacker },
    }
}

fn vector_state(value: BattleScriptTrysetgrudgeRules) -> BattleScriptTrysetgrudgeVectorState {
    BattleScriptTrysetgrudgeVectorState {
        status3: value.battlers.map(|battler| battler.status3),
        attacker: value.selector_roles.attacker,
    }
}

#[test]
fn complete_projected_outputs_controls_and_exact_missing_role_error_match_canonical_typescript() {
    assert_eq!(BATTLE_SCRIPT_TRYSETGRUDGE_CASES.len(), 45);
    for (case_index, case) in BATTLE_SCRIPT_TRYSETGRUDGE_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptTrysetgrudgeVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_trysetgrudge(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact missing-attacker error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptTrysetgrudgeVectorCase,
    application: u8,
    prior: BattleScriptTrysetgrudgeRules,
    outcome: BattleScriptTrysetgrudgeOutcome,
) {
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    assert_eq!(
        outcome.rules.selector_roles, prior.selector_roles,
        "case {case_index} {} application {application}: changed attacker role",
        case.label,
    );

    match outcome.control {
        // This unit-like enum variant deliberately cannot contain the canonical
        // machine's resolved absolute program counter.
        BattleScriptTrysetgrudgeControl::FailJump => {
            assert_ne!(
                prior.battlers[attacker.index()].status3 & BATTLE_SCRIPT_STATUS3_GRUDGE,
                0,
                "case {case_index} {} application {application}: fail jump accepted a clear Grudge bit",
                case.label,
            );
            assert_eq!(
                outcome.rules, prior,
                "case {case_index} {} application {application}: fail jump changed complete narrow state",
                case.label,
            );
        }
        BattleScriptTrysetgrudgeControl::Advance => {
            assert_eq!(
                prior.battlers[attacker.index()].status3 & BATTLE_SCRIPT_STATUS3_GRUDGE,
                0,
                "case {case_index} {} application {application}: advance accepted an already-Grudged attacker",
                case.label,
            );
            for battler in BATTLE_SCRIPT_TRYSETGRUDGE_BATTLERS {
                if battler != attacker {
                    assert_eq!(
                        outcome.rules.battlers[battler.index()],
                        prior.battlers[battler.index()],
                        "case {case_index} {} application {application}: changed non-attacker battler {}",
                        case.label,
                        battler.as_u8(),
                    );
                }
            }
            assert_eq!(
                outcome.rules.battlers[attacker.index()].status3,
                prior.battlers[attacker.index()].status3 | BATTLE_SCRIPT_STATUS3_GRUDGE,
                "case {case_index} {} application {application}: did not OR STATUS3_GRUDGE into attacker",
                case.label,
            );
            assert_eq!(
                outcome.rules.battlers[attacker.index()].status3 & !BATTLE_SCRIPT_STATUS3_GRUDGE,
                prior.battlers[attacker.index()].status3 & !BATTLE_SCRIPT_STATUS3_GRUDGE,
                "case {case_index} {} application {application}: changed unrelated attacker status3 bits",
                case.label,
            );
        }
    }
}

#[test]
fn attacker_matrix_covers_all_four_attackers_and_clear_set_grudge_inputs() {
    let matrix = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .filter(|case| case.category == "attacker-grudge-input-matrix")
        .collect::<Vec<_>>();
    assert_eq!(matrix.len(), 8);
    let observed = matrix
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("matrix case {} is missing attacker", case.label));
            (attacker.as_u8(), case.initial.status3[attacker.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_TRYSETGRUDGE_ATTACKER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_TRYSETGRUDGE_GRUDGE_INPUT_DOMAIN
                .into_iter()
                .map(move |status3| (attacker, status3))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);

    for case in matrix {
        let attacker = case.initial.attacker.expect("matrix attacker");
        let expected_control =
            if case.initial.status3[attacker.index()] & BATTLE_SCRIPT_STATUS3_GRUDGE == 0 {
                BattleScriptTrysetgrudgeControl::Advance
            } else {
                BattleScriptTrysetgrudgeControl::FailJump
            };
        assert_eq!(
            case.controls,
            &[expected_control],
            "branch predicate for {}",
            case.label,
        );
    }
}

#[test]
fn status3_u32_edges_cover_every_attacker_and_only_test_the_grudge_bit() {
    let edges = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .filter(|case| case.category == "status3-u32-edge-matrix")
        .collect::<Vec<_>>();
    assert_eq!(edges.len(), 32);
    let observed = edges
        .iter()
        .map(|case| {
            let attacker = case
                .initial
                .attacker
                .unwrap_or_else(|| panic!("edge case {} is missing attacker", case.label));
            (attacker.as_u8(), case.initial.status3[attacker.index()])
        })
        .collect::<BTreeSet<_>>();
    let expected = BATTLE_SCRIPT_TRYSETGRUDGE_ATTACKER_DOMAIN
        .into_iter()
        .flat_map(|attacker| {
            BATTLE_SCRIPT_TRYSETGRUDGE_STATUS3_EDGE_DOMAIN
                .into_iter()
                .map(move |status3| (attacker, status3))
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);

    for case in edges {
        let attacker = case.initial.attacker.expect("edge attacker");
        let initial_status3 = case.initial.status3[attacker.index()];
        let expected_control = if initial_status3 & BATTLE_SCRIPT_STATUS3_GRUDGE == 0 {
            BattleScriptTrysetgrudgeControl::Advance
        } else {
            BattleScriptTrysetgrudgeControl::FailJump
        };
        assert_eq!(
            case.controls,
            &[expected_control],
            "status3 edge branch for {}",
            case.label,
        );
    }
}

#[test]
fn sibling_preservation_missing_role_fail_jump_and_repeated_behavior_are_pinned() {
    let mutation = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .find(|case| case.label == "clear_branch_mutates_only_attacker_preserves_siblings")
        .expect("attacker-only mutation vector");
    let mutation_expected = mutation.expected.expect("attacker-only mutation output");
    assert_eq!(
        mutation.initial.attacker.map(|value| value.as_u8()),
        Some(2)
    );
    assert_eq!(mutation.initial.status3[2], 0x8000_0101);
    assert_eq!(mutation_expected.status3[2], 0x8000_4101);
    for battler in [0, 1, 3] {
        assert_eq!(
            mutation_expected.status3[battler], mutation.initial.status3[battler],
            "attacker-only mutation changed sibling {battler}",
        );
    }

    let failure = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .find(|case| {
            case.label == "already_grudged_fail_jump_preserves_all_status3_without_program_counter"
        })
        .expect("already-Grudged fail-jump vector");
    assert_eq!(failure.initial.attacker.map(|value| value.as_u8()), Some(1));
    assert_eq!(failure.initial.status3[1], 0x8000_4101);
    assert_eq!(
        failure.controls,
        &[BattleScriptTrysetgrudgeControl::FailJump],
    );
    assert_eq!(failure.expected, Some(failure.initial));

    let missing = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .find(|case| {
            case.label
                == "missing_attacker_role_precedes_status3_read_and_failure_target_resolution"
        })
        .expect("missing-attacker vector");
    assert_eq!(missing.initial.attacker, None);
    assert_eq!(missing.initial.status3[2], u32::MAX);
    assert_eq!(missing.expected, None);
    assert!(missing.controls.is_empty());
    assert_eq!(
        missing.expected_error,
        Some("Battle Script hit-chain command requires a attacker role"),
    );

    let repeated_clear = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .find(|case| case.label == "repeated_clear_application_advances_then_fail_jumps")
        .expect("repeated clear vector");
    let repeated_clear_expected = repeated_clear.expected.expect("repeated clear output");
    assert_eq!(repeated_clear.applications, 2);
    assert_eq!(
        repeated_clear.controls,
        &[
            BattleScriptTrysetgrudgeControl::Advance,
            BattleScriptTrysetgrudgeControl::FailJump,
        ],
    );
    assert_eq!(repeated_clear_expected.status3[3], 0x8000_4101);

    let repeated_failure = BATTLE_SCRIPT_TRYSETGRUDGE_CASES
        .iter()
        .find(|case| case.label == "repeated_already_grudged_fail_jump_is_idempotent")
        .expect("repeated fail-jump vector");
    assert_eq!(repeated_failure.applications, 2);
    assert_eq!(
        repeated_failure.controls,
        &[
            BattleScriptTrysetgrudgeControl::FailJump,
            BattleScriptTrysetgrudgeControl::FailJump,
        ],
    );
    assert_eq!(repeated_failure.expected, Some(repeated_failure.initial));
}

#[test]
fn fixed_four_slot_u32_domains_and_source_constant_are_retained() {
    assert_eq!(BATTLE_SCRIPT_TRYSETGRUDGE_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_TRYSETGRUDGE_ATTACKER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_TRYSETGRUDGE_ATTACKER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_GRUDGE_INPUT_DOMAIN,
        [0x0000_0000, 0x0000_4000],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_STATUS3_EDGE_DOMAIN,
        [
            0x0000_0000,
            0xffff_ffff,
            0x8000_0000,
            0x0100_0001,
            0x0000_3fff,
            0x0000_4000,
            0x0000_4001,
            0xffff_bfff,
        ],
    );
    assert_eq!(BATTLE_SCRIPT_STATUS3_GRUDGE, 0x0000_4000);
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("optional-attacker-role-values", 5),
            ("status3-u32-values", 4_294_967_296),
            ("status3-grudge-clear-set-inputs", 2),
            ("status3-u32-edge-values", 8),
            ("control-branch-values", 2),
            ("application-count-values", 2),
            ("typed-missing-attacker-combinations", 1),
            ("absolute-program-counter-fields-in-projection", 0),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_CATEGORY_CENSUS,
        [
            ("already-grudged-fail-jump-preservation", 1),
            ("attacker-grudge-input-matrix", 8),
            ("attacker-only-mutation", 1),
            ("missing-attacker-role", 1),
            ("repeated-already-grudged-fail-jump", 1),
            ("repeated-clear-then-fail-jump", 1),
            ("status3-u32-edge-matrix", 32),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_BRANCH_CENSUS,
        [
            ("advance", 25),
            ("advance-then-fail-jump", 1),
            ("fail-jump", 17),
            ("fail-jump-then-fail-jump", 1),
            ("missing-attacker-role", 1),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETGRUDGE_VECTOR_CORPUS_SHA256,
        "b38e387bb68c4390978018c580352dc7d4a05fcac7929354d011e8a5e944d675",
    );
}
